keyConcepts.codeExample:
// src/internal/vat-rates.ts (non exporté publiquement)
export const VAT_RATES = { FR: 0.2, DE: 0.19 };

// src/invoice-service.ts
import { VAT_RATES } from './internal/vat-rates';

export class InvoiceService {
  vatFor(country: keyof typeof VAT_RATES): number {
    return VAT_RATES[country];
  }
}

// index.ts : seule porte d'entrée publique du paquet
export { InvoiceService } from './invoice-service';

